import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.B7PviQjB.js";const s="/docs/images/collaborate/workspaces-switcher.png",n="/docs/images/collaborate/workspaces-invites.png",k=JSON.parse('{"title":"Manage workspaces and members","description":"Create and switch workspaces, invite and remove members, and see what owners and members can do.","frontmatter":{"title":"Manage workspaces and members","description":"Create and switch workspaces, invite and remove members, and see what owners and members can do.","type":"how-to"},"headers":[],"relativePath":"collaborate/workspaces.md","filePath":"collaborate/workspaces.md"}'),i={name:"collaborate/workspaces.md"};function d(l,e,c,h,p,m){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="manage-workspaces-and-members" tabindex="-1">Manage workspaces and members <a class="header-anchor" href="#manage-workspaces-and-members" aria-label="Permalink to &quot;Manage workspaces and members&quot;">​</a></h1><p>A workspace holds your documents, folders, data sources, and API keys, and its members are the people who can open them.</p><p>Every member can open and edit every document in the workspace. To share one document with someone outside it, use a <a href="/docs/collaborate/share.html">share link</a> instead.</p><h2 id="create-a-workspace" tabindex="-1">Create a workspace <a class="header-anchor" href="#create-a-workspace" aria-label="Permalink to &quot;Create a workspace&quot;">​</a></h2><p>You already have one: the first time you sign in, Wafflebase creates <strong>&lt;your username&gt;&#39;s Workspace</strong> and makes you its owner.</p><ol><li>Click the workspace name at the top of the sidebar.</li><li>Select <strong>New workspace</strong>.</li><li>Enter a name and click <strong>Create</strong>.</li></ol><p>The new workspace opens, and you are its owner.</p><h2 id="switch-workspaces" tabindex="-1">Switch workspaces <a class="header-anchor" href="#switch-workspaces" aria-label="Permalink to &quot;Switch workspaces&quot;">​</a></h2><ol><li>Click the workspace name at the top of the sidebar.</li><li>Select the workspace you want.</li></ol><p>Its documents list opens. Each workspace has its own address, <code>/w/&lt;workspace-url&gt;</code>, and its own documents, templates, data sources, and trash.</p><p><img src="'+s+'" alt="Sidebar workspace switcher open with two workspaces and New workspace"></p><h3 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h3><p>Tap the sidebar button at the top left of the header to open the sidebar, then use the switcher the same way. The sidebar closes when you pick a workspace.</p><h2 id="invite-someone" tabindex="-1">Invite someone <a class="header-anchor" href="#invite-someone" aria-label="Permalink to &quot;Invite someone&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>Only an owner can invite.</li><li>Wafflebase doesn&#39;t send email. You copy the link and send it yourself.</li></ul></div><ol><li>In the sidebar, click <strong>Settings</strong>.</li><li>Under <strong>Invites</strong>, click <strong>Create invite link</strong>.</li><li>In the new row, click the copy icon (<strong>Copy invite link</strong>).</li><li>Send the link to the person you want to invite.</li></ol><p>When they open the link, they sign in if needed and land in the workspace&#39;s documents list as a member. Opening it as an existing member changes nothing. The workspace owners and the person who created the invite get a <a href="/docs/collaborate/comments.html#get-notified">notification</a> when someone joins.</p><div class="warning custom-block"><p class="custom-block-title">An invite link works for anyone who has it</p><p>The link isn&#39;t tied to an email address, never expires, and can be used by more than one person. Treat it like a password and revoke it when you&#39;re done.</p></div><p><img src="'+n+'" alt="Settings page with the Members table and one invite row with copy and revoke icons"></p><h2 id="revoke-an-invite" tabindex="-1">Revoke an invite <a class="header-anchor" href="#revoke-an-invite" aria-label="Permalink to &quot;Revoke an invite&quot;">​</a></h2><ol><li>Open <strong>Settings</strong>.</li><li>Under <strong>Invites</strong>, click the trash icon (<strong>Revoke invite</strong>) in the invite&#39;s row.</li></ol><p>The link stops working right away. People who already joined with it stay members.</p><h2 id="remove-a-member-or-leave" tabindex="-1">Remove a member or leave <a class="header-anchor" href="#remove-a-member-or-leave" aria-label="Permalink to &quot;Remove a member or leave&quot;">​</a></h2><ol><li>Open <strong>Settings</strong>.</li><li>Under <strong>Members</strong>, click the trash icon (<strong>Remove member</strong>) in the person&#39;s row.</li></ol><p>The member is removed right away, with no confirmation. An owner sees the icon on every member&#39;s row, but never on an owner&#39;s row. A member sees it only on their own row, which is how you leave a workspace.</p><p>When someone is removed:</p><ul><li>They lose access to every document, folder, and data source in the workspace. Their other workspaces are unaffected.</li><li>The documents they created stay in the workspace and keep them as the author.</li><li>Their API keys for this workspace are revoked for good. Adding them back doesn&#39;t bring the keys back.</li></ul><h2 id="rename-the-workspace-or-change-its-url" tabindex="-1">Rename the workspace or change its URL <a class="header-anchor" href="#rename-the-workspace-or-change-its-url" aria-label="Permalink to &quot;Rename the workspace or change its URL&quot;">​</a></h2><ol><li>Open <strong>Settings</strong>.</li><li>Edit <strong>Workspace name</strong> or <strong>Workspace URL</strong>.</li><li>Click <strong>Save</strong> next to the field you changed.</li></ol><p>Only an owner can save these changes; a member who tries sees <em>Couldn&#39;t update the workspace</em>. Links to documents keep working after a URL change, but links to the old <code>/w/&lt;workspace-url&gt;</code> address stop working.</p><h2 id="delete-a-workspace" tabindex="-1">Delete a workspace <a class="header-anchor" href="#delete-a-workspace" aria-label="Permalink to &quot;Delete a workspace&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Deleting a workspace can&#39;t be undone</p><p>It permanently deletes every document, folder, data source, invite, and API key in it. Deleted documents don&#39;t go to the <a href="/docs/collaborate/trash.html">Trash</a>.</p></div><ol><li>Open <strong>Settings</strong> as an owner.</li><li>Under <strong>Delete workspace</strong>, click <strong>Delete this workspace</strong>.</li><li>Type the workspace&#39;s name to confirm.</li><li>Click <strong>Delete workspace</strong>.</li></ol><p>You can&#39;t delete your last workspace.</p><h2 id="see-who-viewed-shared-documents" tabindex="-1">See who viewed shared documents <a class="header-anchor" href="#see-who-viewed-shared-documents" aria-label="Permalink to &quot;See who viewed shared documents&quot;">​</a></h2><p><strong>Analytics</strong> appears in the sidebar only when your deployment has turned on view analytics. It counts visits through <a href="/docs/collaborate/share.html">share links</a>.</p><ol><li>In the sidebar, click <strong>Analytics</strong>.</li><li>Pick a date range: <strong>Last 7 days</strong>, <strong>Last 30 days</strong> (the default), <strong>Last 90 days</strong>, or <strong>All time</strong>.</li><li>To see one document&#39;s numbers, click <strong>Details</strong> in its row under <strong>Most viewed documents</strong>.</li></ol><p>The workspace page shows <strong>Total views</strong>, <strong>Unique visitors</strong>, and the most viewed documents. A document&#39;s page adds <strong>Returning visitors</strong>, <strong>Avg. dwell</strong>, and views per share link. <strong>Details</strong> appears only on documents you created, or on every document if you own the workspace.</p><h2 id="check-what-each-role-can-do" tabindex="-1">Check what each role can do <a class="header-anchor" href="#check-what-each-role-can-do" aria-label="Permalink to &quot;Check what each role can do&quot;">​</a></h2><p>A workspace has two roles. Whoever creates it is the <strong>owner</strong>, and everyone who joins with an invite link is a <strong>member</strong>.</p><p>Some actions need you to <em>manage</em> the document or folder: you created it, or you own the workspace.</p><table tabindex="0"><thead><tr><th>Action</th><th>Member</th><th>Owner</th></tr></thead><tbody><tr><td>Open, create, edit, rename, and copy documents</td><td>Yes</td><td>Yes</td></tr><tr><td>Comment, and see version history</td><td>Yes</td><td>Yes</td></tr><tr><td>Move a document, or move it to the Trash</td><td>Ones you created</td><td>Yes</td></tr><tr><td>Restore or delete forever from the Trash</td><td>Ones you created</td><td>Yes</td></tr><tr><td>Create and rename folders</td><td>Yes</td><td>Yes</td></tr><tr><td>Move or delete a folder</td><td>Ones you created</td><td>Yes</td></tr><tr><td>Create a viewer share link</td><td>Yes</td><td>Yes</td></tr><tr><td>Create an editor share link, or publish a template</td><td>Ones you created</td><td>Yes</td></tr><tr><td>Revoke a share link</td><td>Links you created, and any link on documents you created</td><td>Any link</td></tr><tr><td>Use and edit data sources</td><td>Yes</td><td>Yes</td></tr><tr><td>Create API keys, and see and revoke them</td><td>Your own</td><td>Everyone&#39;s</td></tr><tr><td>Invite people and revoke invites</td><td>No</td><td>Yes</td></tr><tr><td>Remove a member</td><td>Only yourself</td><td>Any member</td></tr><tr><td>Rename the workspace or change its URL</td><td>No</td><td>Yes</td></tr><tr><td>Delete the workspace</td><td>No</td><td>Yes</td></tr></tbody></table><p>Roles are fixed. The app has no way to promote a member, transfer ownership, or let an owner leave, so decide who should own a workspace before you invite people.</p><div class="warning custom-block"><p class="custom-block-title">Folders don&#39;t restrict access</p><p>Every member can open every document, whatever folder it&#39;s in. Keep content that some members shouldn&#39;t see in a separate workspace.</p></div><p>Data source connections belong to the workspace, so any member can query them with the saved credentials. See <a href="/docs/sheets/connect-a-database.html">Connect a database</a>.</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>Invite links from Settings always add a member and never expire.</li><li>An owner can&#39;t leave a workspace or be removed from it in the app.</li><li>People who open a share link aren&#39;t members. They can&#39;t be mentioned or notified.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/collaborate/share.html">Share a document</a> with people outside the workspace.</li><li><a href="/docs/collaborate/folders.html">Folders</a> to organize a workspace&#39;s documents.</li><li><a href="/docs/start/concepts.html">Concepts</a> for how workspaces, share links, and templates relate.</li><li><a href="/docs/developers/api/quickstart.html">API quickstart</a> to create and use an API key.</li></ul>',49)])])}const u=t(i,[["render",d]]);export{k as __pageData,u as default};
